"""API request handling.

All requests must pass signature verification before their payload is processed.
"""


def _validate_request(data, signature):
    """Raise ``PermissionError`` if *signature* does not authenticate *data*."""
    signature_is_valid = verify_signature(data, signature)
    if not signature_is_valid:
        raise PermissionError("invalid signature")


def handle_request(data, signature):
    """Validate the request and process its payload."""
    _validate_request(data, signature)
    return process(data)

